head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setHeaderValue]<br/>Header Cell 정보를 사용하여 특정 Header Cell 의 데이터를 설정합니다.",
    "validation" : [
        "useFormat(선택) 파라미터에 true 설정 시, displayFormat 또는 displayFormatter 속성이 적용되는 조건일때 해당 속성을 활성화하여 데이터에 반영해야 합니다.",
        "useFormat(선택) 파라미터에 false 설정 시, displayFormat 또는 displayFormatter 속성을 적용하지 않아야 합니다.",
        "useFormat(선택) 파라미터 생략 시, 기본값 false 로 동작하여 displayFormat 또는 displayFormatter 속성을 적용하지 않아야 합니다.",
        "Header Cell 의 displayFormatter 속성이 설정된 경우 displayFormat 속성은 무시되어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 파라미터 기본값 설정 (gdl_boolean : 1=미설정, 2=true, 3=false)
    par_useFormat.setValue("1");

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 테스트 참고 라벨 생성
    $c.gcm.createLabel('label="[전제] Header Cell 포맷 구성 - hd1: displayFormat(####-##-##) / hd2: displayFormatter(대괄호) / hd3: displayFormat + displayFormatter 모두 설정 / hd4: 포맷 미설정\n[절차] headerId, value, useFormat 선택 후 setHeaderValue 버튼 실행 (useFormat 을 빈값으로 두면 파라미터를 생략하여 호출)\n[확인] 결과창의 Header 표시 텍스트와 그리드 Header Cell 에 실제 표시된 텍스트를 대비"', '', 'label1');

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (Header Cell 별 displayFormat / displayFormatter 설정)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:250px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" dataType="text" displayFormat="####-##-##" id="hd1" value="hd1(format)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" dataType="text" displayFormatter="function(data){ return \'[\' + data + \']\'; }" id="hd2" value="hd2(formatter)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" dataType="text" displayFormat="####-##-##" displayFormatter="function(data){ return \'(\' + data + \')\'; }" id="hd3" value="hd3(both)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" dataType="text" id="hd4" value="hd4(none)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Header Cell 에 실제 표시된 텍스트 조회
scwin.getHeaderText = function (headerId) {
    let ths = document.querySelectorAll("th[id*='target1']");

    for (let i = 0; i < ths.length; i++) {
        let hid = ths[i].getAttribute("data-header_id") || ths[i].getAttribute("header_id");

        if (hid != null && hid.toLowerCase() === headerId.toLowerCase()) {
            return ths[i].textContent;
        }
    }

    return "";
}



scwin.btn_setHeaderValue_onclick = function () {
    let headerId = par_headerId.getValue();
    let value = par_value.getValue();
    let useFormat = par_useFormat.getText();
    let strCall = "";

    if (useFormat === '') {
        // useFormat 생략 호출 (기본값 false 동작 확인)
        target1.setHeaderValue(headerId, value);
        strCall = "setHeaderValue('" + headerId + "', '" + value + "')";
    } else {
        target1.setHeaderValue(headerId, value, useFormat === 'true');
        strCall = "setHeaderValue('" + headerId + "', '" + value + "', " + useFormat + ")";
    }

    wf_body_bottom.getObj("scwin").setReturnValue(strCall + " -> Header 표시 텍스트 : " + scwin.getHeaderText(headerId));
}
